INSERT INTO `journal_encounter_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2879, 'koKR', '격동하는 똬리', '울라텍의 자손들이 서로를 잡아먹는 광란의 도가니 속에서, 다른 개체들을 모두 꺾고 살아남은 존재가 하나 있습니다. 격동하는 똬리라는 명칭으로 불리는 이 기괴한 괴수는 전투에서 이길 때마다 더욱더 강해집니다.', 69497);
