INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(3058, 'koKR', '격동하는 무리', '|cFFFFD200획득: |r줄잔|n|cFFFFD200지역:|r 송곳니의 제단', '기괴한 뱀들이 한데 뒤엉킨 덩어리입니다. 당신이 격동하는 똬리와 맞서 싸우는 모습을 보고 끝내 고개를 숙였습니다.', 69497);
